@pytest.mark.parametrize('kwargs,expected', [(dict(), np.rec.array([(0, 1, 0.2, 'a'), (1, 2, 1.5, 'bc')], dtype=[('index', '<i8'), ('A', '<i8'), ('B', '<f8'), ('C', 'O')])), (dict(index=True), np.rec.array([(0, 1, 0.2, 'a'), (1, 2, 1.5, 'bc')], dtype=[('index', '<i8'), ('A', '<i8'), ('B', '<f8'), ('C', 'O')])), (dict(column_dtypes='<U4'), np.rec.array([('0', '1', '0.2', 'a'), ('1', '2', '1.5', 'bc')], dtype=[('index', '<i8'), ('A', '<U4'), ('B', '<U4'), ('C', '<U4')])), (dict(index_dtypes='<U1'), np.rec.array([('0', 1, 0.2, 'a'), ('1', 2, 1.5, 'bc')], dtype=[('index', '<U1'), ('A', '<i8'), ('B', '<f8'), ('C', 'O')])), (dict(column_dtypes=np.unicode), np.rec.array([('0', '1', '0.2', 'a'), ('1', '2', '1.5', 'bc')], dtype=[('index', '<i8'), ('A', '<U'), ('B', '<U'), ('C', '<U')])), (dict(column_dtypes=np.dtype('unicode')), np.rec.array([('0', '1', '0.2', 'a'), ('1', '2', '1.5', 'bc')], dtype=[('index', '<i8'), ('A', '<U'), ('B', '<U'), ('C', '<U')])), (dict(column_dtypes={'A': np.int8, 'B': np.float32, 'C': '<U2'}), np.rec.array([('0', '1', '0.2', 'a'), ('1', '2', '1.5', 'bc')], dtype=[('index', '<i8'), ('A', 'i1'), ('B', '<f4'), ('C', '<U2')])), (dict(index_dtypes={0: 'int16'}), np.rec.array([(0, 1, 0.2, 'a'), (1, 2, 1.5, 'bc')], dtype=[('index', 'i2'), ('A', '<i8'), ('B', '<f8'), ('C', 'O')])), (dict(index=False, index_dtypes='<U2'), np.rec.array([(1, 0.2, 'a'), (2, 1.5, 'bc')], dtype=[('A', '<i8'), ('B', '<f8'), ('C', 'O')])), (dict(index_dtypes={0: 'int16', 'not-there': 'float32'}), np.rec.array([(0, 1, 0.2, 'a'), (1, 2, 1.5, 'bc')], dtype=[('index', 'i2'), ('A', '<i8'), ('B', '<f8'), ('C', 'O')])), (dict(column_dtypes={'A': np.int8, 'B': np.float32}), np.rec.array([('0', '1', '0.2', 'a'), ('1', '2', '1.5', 'bc')], dtype=[('index', '<i8'), ('A', 'i1'), ('B', '<f4'), ('C', 'O')])), (dict(column_dtypes={'A': np.dtype('int8'), 'B': np.dtype('float32')}), np.rec.array([('0', '1', '0.2', 'a'), ('1', '2', '1.5', 'bc')], dtype=[('index', '<i8'), ('A', 'i1'), ('B', '<f4'), ('C', 'O')])), (dict(column_dtypes={'A': np.int8, 'B': np.float32}, index_dtypes='<U2'), np.rec.array([('0', '1', '0.2', 'a'), ('1', '2', '1.5', 'bc')], dtype=[('index', '<U2'), ('A', 'i1'), ('B', '<f4'), ('C', 'O')])), (dict(index=False, column_dtypes=list()), (ValueError, 'Invalid dtype \\[\\] specified for column A')), (dict(index=False, column_dtypes={'A': 'int32', 'B': 5}), (ValueError, 'Invalid dtype 5 specified for column B')), (dict(index=False, column_dtypes={'A': 'int32', 'B': CategoricalDtype(['a', 'b'])}), (ValueError, 'Invalid dtype category specified for column B')), (dict(index=False, column_dtypes={'A': 'int32', 'B': 'foo'}), (TypeError, 'data type ["\']foo["\'] not understood'))])
def test_to_records_dtype(self, kwargs, expected):
    df = DataFrame({'A': [1, 2], 'B': [0.2, 1.5], 'C': ['a', 'bc']})
    if not isinstance(expected, np.recarray):
        with pytest.raises(expected[0], match=expected[1]):
            df.to_records(**kwargs)
    else:
        result = df.to_records(**kwargs)
        tm.assert_almost_equal(result, expected)